//autogenerated:yes
//nolint:revive,govet,errcheck
package storm32_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/storm32"
	"github.com/stretchr/testify/require"
)

func TestEnum_MAV_STORM32_GIMBAL_MANAGER_CAP_FLAGS(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.MAV_STORM32_GIMBAL_MANAGER_CAP_FLAGS
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.MAV_STORM32_GIMBAL_MANAGER_CAP_FLAGS_HAS_PROFILES.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.MAV_STORM32_GIMBAL_MANAGER_CAP_FLAGS
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.MAV_STORM32_GIMBAL_MANAGER_CAP_FLAGS_HAS_PROFILES, dec)
	})
}
